class MemorySystem:
    def __init__(self):
        self.short_term = []  # Recent context
        self.long_term = VectorDB()  # Persistent storage
    def store(self, content): self.long_term.add(content)
    def retrieve(self, query): return self.long_term.search(query, top_k=5)
    def forget(self): self._cleanup_low_value()
